<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();$s=db()->prepare('SELECT rc.code_reference,rc.status,rc.expires_at,rc.created_at,rc.redeemed_at,g.name gift,g.description,g.campaign FROM reward_codes rc JOIN gifts g ON g.id=rc.gift_id WHERE rc.user_id=? ORDER BY rc.id DESC');$s->execute([$user['id']]);json_response(true,'Reward codes',['items'=>$s->fetchAll()]);
